<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import { researchApi,type RecordItem } from '@/api/research'
interface Field{name:string;type:string;options?:string}
interface Row{id:string;title:string;values:Record<string,string>}
const items=ref<RecordItem[]>([]),active=ref<RecordItem>(),title=ref('我的学习资料'),fields=ref<Field[]>([{name:'学科',type:'text'},{name:'掌握程度',type:'select',options:'待学习,学习中,已掌握'},{name:'下次复习',type:'date'},{name:'来源',type:'text'}]),rows=ref<Row[]>([])
const view=ref('table'),fieldName=ref(''),fieldType=ref('text'),fieldOptions=ref(''),error=ref(''),busy=ref(false),dirty=ref(false),page=ref(0)
const mayLeave=()=>!busy.value&&(!dirty.value||confirm('资料表有未保存修改，确认离开？'))
onBeforeRouteLeave(mayLeave)
onBeforeRouteUpdate((to,from)=>to.query.tab===from.query.tab||mayLeave())
const boardField=computed(()=>fields.value.find(f=>f.type==='select')),dateField=computed(()=>fields.value.find(f=>f.type==='date'))
const stages=computed(()=>[...new Set(['未分类',...(boardField.value?.options||'').split(/[,，]/).filter(Boolean),...rows.value.map(r=>r.values[boardField.value?.name||'']||'未分类')])])
const month=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1))
const calendar=computed(()=>{const start=new Date(month.value);start.setDate(1-((start.getDay()+6)%7));return Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return{key,day:d.getDate(),current:d.getMonth()===month.value.getMonth(),rows:rows.value.filter(r=>r.values[dateField.value?.name||'']===key)}})})
function removeField(f:Field){if(confirm('删除字段 '+f.name+'？')){fields.value=fields.value.filter(v=>v!==f);dirty.value=true}}
function addRow(){rows.value.push({id:crypto.randomUUID(),title:'新资料',values:{}});dirty.value=true}
function changeMonth(n:number){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+n,1)}
async function load(){try{items.value=await researchApi.records('COLLECTION',page.value)}catch(e){error.value=(e as Error).message}}
function choose(i:RecordItem){if(dirty.value&&!confirm('当前资料表尚未保存，放弃这些修改？'))return;active.value=i;title.value=i.title;fields.value=structuredClone(i.data.fields);rows.value=structuredClone(i.data.rows);dirty.value=false}
function create(){if(dirty.value&&!confirm('放弃当前未保存修改？'))return;active.value=undefined;title.value='新的资料表';rows.value=[];dirty.value=true}
function addField(){const name=fieldName.value.trim();if(!name||fields.value.some(f=>f.name===name)||fields.value.length>=16){error.value='字段名不能为空、不能重复，最多 16 个字段';return}fields.value.push({name,type:fieldType.value,options:fieldOptions.value});fieldName.value='';fieldOptions.value='';dirty.value=true}
async function save(){if(busy.value)return;busy.value=true;error.value='';const snapshot=JSON.stringify({title:title.value,fields:fields.value,rows:rows.value});try{const submitted=JSON.parse(snapshot);active.value=await researchApi.save('COLLECTION',submitted.title,{fields:submitted.fields,rows:submitted.rows},active.value);dirty.value=snapshot!==JSON.stringify({title:title.value,fields:fields.value,rows:rows.value});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(){if(!active.value||!confirm('永久删除这张资料表？'))return;busy.value=true;try{await researchApi.delete(active.value);active.value=undefined;rows.value=[];dirty.value=false;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div><p v-if="error" role="alert" class="inline-alert inline-alert--error">{{ error }}</p><div class="collection-top"><select class="field-input" :value="active?.id||''" aria-label="选择资料表" @change="choose(items.find(i=>i.id===($event.target as HTMLSelectElement).value)!)"><option value="" disabled>选择已保存资料表</option><option v-for="i in items" :key="i.id" :value="i.id">{{ i.title }}</option></select><button class="button button--ghost" @click="create">新建资料表</button><button class="button button--dark" :disabled="busy||!title.trim()" @click="save">{{ busy?'保存中…':dirty?'保存修改':'保存资料表' }}</button><button v-if="active" class="button button--ghost" :disabled="busy" @click="remove">删除</button></div>
 <input v-model="title" class="collection-title" aria-label="资料表名称" maxlength="180" @input="dirty=true"/>
 <p class="research-hint">同一份资料可以用表格、看板与月历浏览。第一个选项字段用于看板，第一个日期字段用于月历。</p>
 <div class="research-actions"><button v-for="v in [['table','表格'],['board','看板'],['calendar','月历']]" :key="v[0]" class="button" :class="view===v[0]?'button--dark':'button--ghost'" @click="view=v[0]||'table'">{{ v[1] }}</button><button class="button button--ghost" :disabled="rows.length>=500" @click="addRow()">＋ 添加资料</button></div>
 <details class="collection-fields"><summary>管理字段</summary><div class="source-chips"><button v-for="f in fields" :key="f.name" @click="removeField(f)">{{ f.name }} ×</button></div><div class="research-actions"><input v-model="fieldName" maxlength="40" class="field-input" placeholder="字段名称" aria-label="字段名称"/><select v-model="fieldType" class="field-input" aria-label="字段类型"><option value="text">文字</option><option value="number">数字</option><option value="select">选项</option><option value="date">日期</option></select><input v-if="fieldType==='select'" v-model="fieldOptions" maxlength="500" class="field-input" placeholder="选项用逗号分隔"/><button class="button button--ghost" @click="addField">添加字段</button></div></details>
 <div v-if="view==='table'" class="collection-scroll"><table class="research-table"><thead><tr><th>资料名称</th><th v-for="f in fields" :key="f.name">{{ f.name }}</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><input v-model="r.title" maxlength="180" aria-label="资料名称" @input="dirty=true"/></td><td v-for="f in fields" :key="f.name"><select v-if="f.type==='select'" v-model="r.values[f.name]" :aria-label="f.name" @change="dirty=true"><option value="">未分类</option><option v-for="o in (f.options||'').split(/[,，]/).filter(Boolean)" :key="o">{{ o }}</option></select><input v-else v-model="r.values[f.name]" :type="f.type==='date'?'date':f.type==='number'?'number':'text'" :aria-label="f.name" maxlength="2000" @input="dirty=true"/></td><td><button class="result-title" @click="rows=rows.filter(v=>v.id!==r.id);dirty=true">移除</button></td></tr></tbody></table></div>
 <div v-else-if="view==='board'" class="collection-board"><section v-for="stage in stages" :key="stage"><h3>{{ stage }}</h3><article v-for="r in rows.filter(r=>(r.values[boardField?.name||'']||'未分类')===stage)" :key="r.id"><strong>{{ r.title }}</strong><select v-if="boardField" v-model="r.values[boardField.name]" class="field-input" aria-label="移动分组" @change="dirty=true"><option value="">未分类</option><option v-for="o in stages.filter(s=>s!=='未分类')" :key="o">{{ o }}</option></select></article></section></div>
 <section v-else><p v-if="!dateField">先添加一个日期字段，再为资料安排日期。</p><div class="research-actions"><button class="button button--ghost" @click="changeMonth(-1)">上个月</button><strong>{{ month.getFullYear() }} 年 {{ month.getMonth()+1 }} 月</strong><button class="button button--ghost" @click="changeMonth(1)">下个月</button></div><div class="collection-calendar"><strong v-for="d in ['一','二','三','四','五','六','日']" :key="d">{{ d }}</strong><div v-for="d in calendar" :key="d.key" :class="{muted:!d.current}"><small>{{ d.day }}</small><p v-for="r in d.rows" :key="r.id">{{ r.title }}</p></div></div></section>
 <p v-if="!rows.length" class="research-empty">添加第一条资料，开始整理你的学习计划。</p><div class="research-pagination"><button class="button button--ghost" :disabled="!page" @click="page--;load()">上一页资料表</button><button class="button button--ghost" :disabled="items.length<50" @click="page++;load()">下一页资料表</button></div></div></template>
<style scoped>.collection-top{display:flex;gap:12px}.collection-top select{max-width:320px}.collection-title{border:0;background:none;font-family:inherit;font-weight:550;font-size:24px;padding:28px 0 8px;width:100%;color:var(--ink)}.collection-fields{margin:22px 0;font-size:13px}.collection-scroll{max-width:100%;overflow:auto}.collection-scroll input,.collection-scroll select{width:100%;min-width:140px;border:0;background:none;color:var(--ink);padding:8px;font:inherit}.collection-scroll input:hover,.collection-scroll input:focus{background:var(--paper)}.collection-board{display:flex;gap:18px;overflow:auto;padding:20px 0}.collection-board>section{min-width:250px;flex:1;background:var(--code-paper);padding:16px}.collection-board article{padding:18px;background:var(--paper);border:1px solid var(--line);margin-bottom:12px}.collection-board select{margin-top:15px}.collection-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));margin-top:20px;border-left:1px solid var(--line)}.collection-calendar>div{min-height:110px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);padding:12px}.collection-calendar>strong{padding:15px;font-size:12px;border-bottom:1px solid var(--line)}.collection-calendar p{font-size:12px;background:var(--paper);padding:7px;overflow-wrap:anywhere}.collection-calendar .muted{opacity:.45}</style>
